const test = require('node:test');
const assert = require('node:assert');
const { clean } = require('./strip_attribution.js');

test('removes the environment footer and its separator', () => {
  const body = '## What\n\nStuff\n\n---\n_Generated by [Claude Code](https://claude.ai/code/session_123)_';
  assert.strictEqual(clean(body), '## What\n\nStuff\n');
});

test('removes the robot-emoji variant and a bare session link', () => {
  const body = 'Text\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nhttps://claude.ai/code/session_abc';
  assert.strictEqual(clean(body), 'Text\n');
});

test('removes Co-Authored-By and Claude-Session trailers', () => {
  const body = 'Fix\n\nCo-Authored-By: Claude <noreply@anthropic.com>\nClaude-Session: https://claude.ai/code/x';
  assert.strictEqual(clean(body), 'Fix\n');
});

test('keeps text that only names the forbidden strings', () => {
  const body = 'guard fails on `Co-Authored-By`, `Generated with Claude Code` or `claude.ai/code`.';
  assert.strictEqual(clean(body), null);
});

test('keeps a human co-author trailer', () => {
  assert.strictEqual(clean('Fix\n\nCo-Authored-By: Nithin <n@example.com>'), null);
});

test('returns null for empty or clean bodies', () => {
  assert.strictEqual(clean(''), null);
  assert.strictEqual(clean(null), null);
  assert.strictEqual(clean('Just text\n'), null);
});
